WITH unpacked AS (SELECT id, service, status_code, payload_json, context, COALESCE(context['region'], 'direct') AS region_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier FROM app_logs WHERE service IN ('auth', 'search')) SELECT *, COUNT(status_code) OVER w_ordered AS running_count_status_code, AVG(status_code) OVER w_ordered AS running_avg_status_code, SUM(status_code) OVER w_ordered AS running_sum_status_code, ROW_NUMBER() OVER (PARTITION BY tier ORDER BY status_code DESC, id ASC) AS seq_no FROM unpacked WINDOW w_ordered AS (PARTITION BY service ORDER BY status_code ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
